"use client";

import React from "react";
import {
  Info,
  AlertTriangle,
  CheckCircle2,
  ChevronRight,
  ExternalLink,
  Lightbulb,
  Shield,
  HelpCircle,
  FileText,
  Sparkles,
  Flame,
} from "lucide-react";

interface NotionBlockRendererProps {
  content?: string;
  className?: string;
}

export function NotionBlockRenderer({ content = "", className = "" }: NotionBlockRendererProps) {
  if (!content) return null;

  // Check if content is primarily HTML (generated by visual WYSIWYG editor)
  const isHtml = /<\s*(p|h[1-6]|div|table|ul|ol|blockquote|section|pre)\b[^>]*>/i.test(content);

  if (isHtml) {
    return (
      <div
        className={`notion-prose ${className}`}
        dangerouslySetInnerHTML={{ __html: sanitizeNotionHtml(content) }}
      />
    );
  }

  // Otherwise, render using enhanced Markdown Parser
  const lines = content.split("\n");
  const elements: React.ReactNode[] = [];
  let inCodeBlock = false;
  let codeBlockLines: string[] = [];
  let currentList: { type: "bullet" | "number" | "task"; items: { text: string; checked?: boolean }[] } | null = null;
  let inTable = false;
  let tableRows: string[][] = [];

  const flushTable = () => {
    if (!inTable || tableRows.length === 0) return;
    const header = tableRows[0] || [];
    const body = tableRows.slice(1);

    elements.push(
      <div key={`table-${elements.length}`} className="my-4 overflow-x-auto rounded-xl border border-gp-ink-700">
        <table className="notion-visual-table w-full text-xs">
          <thead>
            <tr>
              {header.map((col, idx) => (
                <th key={idx} className="bg-gp-ink-800 text-white font-bold p-2.5 border border-gp-ink-700">
                  {renderInline(col)}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {body.map((row, rIdx) => (
              <tr key={rIdx} className={rIdx % 2 === 0 ? "bg-gp-ink-950/40" : "bg-gp-ink-800/30"}>
                {row.map((cell, cIdx) => (
                  <td key={cIdx} className="p-2.5 border border-gp-ink-700 text-gp-ink-200">
                    {renderInline(cell)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );

    tableRows = [];
    inTable = false;
  };

  const flushList = () => {
    if (!currentList) return;
    if (currentList.type === "bullet") {
      elements.push(
        <ul key={`list-${elements.length}`} className="space-y-1.5 pl-2 my-2 text-xs sm:text-sm text-gp-ink-200">
          {currentList.items.map((item, idx) => (
            <li key={idx} className="flex items-start gap-2.5">
              <span className="text-gp-ink-300 mt-1 text-3xs leading-none select-none">•</span>
              <span className="flex-1 leading-relaxed">{renderInline(item.text)}</span>
            </li>
          ))}
        </ul>
      );
    } else if (currentList.type === "number") {
      elements.push(
        <ol key={`list-${elements.length}`} className="space-y-1.5 pl-2 my-2 text-xs sm:text-sm text-gp-ink-200">
          {currentList.items.map((item, idx) => (
            <li key={idx} className="flex items-start gap-2.5">
              <span className="text-gp-ink-300 font-mono text-xs select-none">{idx + 1}.</span>
              <span className="flex-1 leading-relaxed">{renderInline(item.text)}</span>
            </li>
          ))}
        </ol>
      );
    } else if (currentList.type === "task") {
      elements.push(
        <ul key={`task-${elements.length}`} className="space-y-1.5 my-2 text-xs sm:text-sm text-gp-ink-200">
          {currentList.items.map((item, idx) => (
            <li key={idx} className="flex items-center gap-2.5">
              <input
                type="checkbox"
                defaultChecked={item.checked}
                readOnly
                className="w-3.5 h-3.5 rounded border-gp-ink-600 bg-gp-ink-800 text-emerald-500 accent-emerald-500"
              />
              <span className={`flex-1 leading-relaxed ${item.checked ? "line-through opacity-60" : ""}`}>
                {renderInline(item.text)}
              </span>
            </li>
          ))}
        </ul>
      );
    }
    currentList = null;
  };

  for (let i = 0; i < lines.length; i++) {
    const rawLine = lines[i];
    const line = rawLine.trim();

    // Table Row: starts and ends with |
    if (line.startsWith("|") && line.endsWith("|")) {
      flushList();
      // Skip markdown separator row like |---|---|
      if (/^\|[\s\-:|]+\|$/.test(line)) {
        continue;
      }
      const cells = line
        .slice(1, -1)
        .split("|")
        .map((c) => c.trim());
      inTable = true;
      tableRows.push(cells);
      continue;
    } else if (inTable) {
      flushTable();
    }

    // Code Block Toggle
    if (line.startsWith("```")) {
      if (inCodeBlock) {
        elements.push(
          <div
            key={`code-${elements.length}`}
            className="my-3 p-3.5 rounded-lg bg-gp-ink-850 border border-gp-ink-650 font-mono text-xs text-gp-sky overflow-x-auto"
          >
            <pre>{codeBlockLines.join("\n")}</pre>
          </div>
        );
        codeBlockLines = [];
        inCodeBlock = false;
      } else {
        flushList();
        inCodeBlock = true;
      }
      continue;
    }

    if (inCodeBlock) {
      codeBlockLines.push(rawLine);
      continue;
    }

    // Divider Line
    if (line === "---" || line === "***" || line === "___") {
      flushList();
      elements.push(<hr key={`hr-${elements.length}`} className="border-gp-ink-700 my-6" />);
      continue;
    }

    // Image Block: ![alt](url)
    const imgMatch = line.match(/^!\[(.*?)\]\((.*?)\)$/);
    if (imgMatch) {
      flushList();
      const alt = imgMatch[1];
      const src = imgMatch[2];
      elements.push(
        <div key={`img-${elements.length}`} className="my-4 space-y-1 text-center">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            src={src}
            alt={alt}
            className="rounded-2xl border border-gp-ink-700 max-h-96 mx-auto object-cover shadow-lg"
          />
          {alt && <p className="text-2xs text-gp-ink-400 italic">{alt}</p>}
        </div>
      );
      continue;
    }

    // Heading 1: #
    if (line.startsWith("# ")) {
      flushList();
      elements.push(
        <h1
          key={`h1-${elements.length}`}
          className="text-2xl sm:text-3xl font-extrabold text-white tracking-tight mt-6 mb-2"
        >
          {renderInline(line.replace(/^#\s+/, ""))}
        </h1>
      );
      continue;
    }

    // Heading 2: ##
    if (line.startsWith("## ")) {
      flushList();
      elements.push(
        <h2
          key={`h2-${elements.length}`}
          className="text-lg sm:text-xl font-bold text-white tracking-tight mt-5 mb-2 pb-1 border-b border-gp-ink-700"
        >
          {renderInline(line.replace(/^##\s+/, ""))}
        </h2>
      );
      continue;
    }

    // Heading 3: ###
    if (line.startsWith("### ")) {
      flushList();
      elements.push(
        <h3
          key={`h3-${elements.length}`}
          className="text-sm sm:text-base font-bold text-gp-ink-50 tracking-wide mt-4 mb-1"
        >
          {renderInline(line.replace(/^###\s+/, ""))}
        </h3>
      );
      continue;
    }

    // Callout Box: > or > [!NOTE] or > [!WARNING]
    if (line.startsWith("> ")) {
      flushList();
      const calloutText = line.replace(/^>\s+/, "");
      let alertType: "info" | "warning" | "tip" | "danger" = "info";
      let cleanText = calloutText;

      if (calloutText.startsWith("[!WARNING]")) {
        alertType = "warning";
        cleanText = calloutText.replace("[!WARNING]", "").trim();
      } else if (calloutText.startsWith("[!TIP]")) {
        alertType = "tip";
        cleanText = calloutText.replace("[!TIP]", "").trim();
      } else if (calloutText.startsWith("[!CAUTION]") || calloutText.startsWith("[!DANGER]")) {
        alertType = "danger";
        cleanText = calloutText.replace(/\[!(CAUTION|DANGER)\]/, "").trim();
      } else if (calloutText.startsWith("[!NOTE]")) {
        cleanText = calloutText.replace("[!NOTE]", "").trim();
      }

      const styles = {
        info: "bg-blue-950/20 border-blue-500/30 text-blue-200",
        warning: "bg-amber-950/20 border-amber-500/30 text-amber-200",
        tip: "bg-emerald-950/20 border-emerald-500/30 text-emerald-200",
        danger: "bg-red-950/20 border-red-500/30 text-red-200",
      };

      const icons = {
        info: <Info className="w-4 h-4 text-blue-400 flex-shrink-0 mt-0.5" />,
        warning: <AlertTriangle className="w-4 h-4 text-amber-400 flex-shrink-0 mt-0.5" />,
        tip: <CheckCircle2 className="w-4 h-4 text-emerald-400 flex-shrink-0 mt-0.5" />,
        danger: <AlertTriangle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />,
      };

      elements.push(
        <div
          key={`callout-${elements.length}`}
          className={`p-3.5 sm:p-4 rounded-xl border flex items-start gap-3 my-3 text-xs sm:text-sm leading-relaxed shadow-sm ${styles[alertType]}`}
        >
          {icons[alertType]}
          <div className="flex-1 space-y-1">{renderInline(cleanText)}</div>
        </div>
      );
      continue;
    }

    // Task list item: - [ ] or - [x]
    const taskMatch = line.match(/^[-*]\s+\[([ xX])\]\s+(.*)$/);
    if (taskMatch) {
      const isChecked = taskMatch[1].toLowerCase() === "x";
      const taskText = taskMatch[2];
      if (!currentList || currentList.type !== "task") {
        flushList();
        currentList = { type: "task", items: [{ text: taskText, checked: isChecked }] };
      } else {
        currentList.items.push({ text: taskText, checked: isChecked });
      }
      continue;
    }

    // Bullet List: - or * or •
    if (line.startsWith("- ") || line.startsWith("* ") || line.startsWith("• ")) {
      const itemText = line.replace(/^[-*•]\s+/, "");
      if (!currentList || currentList.type !== "bullet") {
        flushList();
        currentList = { type: "bullet", items: [{ text: itemText }] };
      } else {
        currentList.items.push({ text: itemText });
      }
      continue;
    }

    // Numbered List: 1. 2. etc
    if (/^\d+\.\s+/.test(line)) {
      const itemText = line.replace(/^\d+\.\s+/, "");
      if (!currentList || currentList.type !== "number") {
        flushList();
        currentList = { type: "number", items: [{ text: itemText }] };
      } else {
        currentList.items.push({ text: itemText });
      }
      continue;
    }

    // Empty Line
    if (!line) {
      flushList();
      continue;
    }

    // Regular Paragraph
    flushList();
    elements.push(
      <p key={`p-${elements.length}`} className="text-xs sm:text-sm text-gp-ink-200 leading-relaxed my-2">
        {renderInline(line)}
      </p>
    );
  }

  flushList();
  flushTable();

  return <div className={`space-y-1 ${className}`}>{elements}</div>;
}

// Inline token renderer supporting Bold, Italic, Underline, Strikethrough, Code, Links, Colors
function renderInline(text: string): React.ReactNode {
  // Pattern tokens:
  // 1. Bold: **text**
  // 2. Italic: *text* or _text_
  // 3. Underline: <u>text</u> or ++text++
  // 4. Strikethrough: ~~text~~ or <s>text</s>
  // 5. Code: `code`
  // 6. Highlight: ==text== or <mark>text</mark>
  // 7. Colored span: <span style="color:...">text</span>
  // 8. Markdown Link: [label](url)
  // 9. Raw URL: https://...

  const parts: React.ReactNode[] = [];
  let remaining = text;
  let keyIdx = 0;

  while (remaining.length > 0) {
    const boldMatch = remaining.match(/\*\*(.*?)\*\*/);
    const underlineTagMatch = remaining.match(/<u>(.*?)<\/u>/i);
    const underlinePlusMatch = remaining.match(/\+\+(.*?)\+\+/);
    const strikeMatch = remaining.match(/~~(.*?)~~/) || remaining.match(/<s>(.*?)<\/s>/i);
    const highlightMatch = remaining.match(/==(.*?)==/) || remaining.match(/<mark>(.*?)<\/mark>/i);
    const codeMatch = remaining.match(/`([^`]+)`/);
    const linkMatch = remaining.match(/\[([^\]]+)\]\(([^)]+)\)/);
    const urlMatch = remaining.match(/(https?:\/\/[^\s]+)/);

    const candidates = [
      boldMatch && boldMatch.index !== undefined ? { type: "bold" as const, index: boldMatch.index, length: boldMatch[0].length, match: boldMatch } : null,
      underlineTagMatch && underlineTagMatch.index !== undefined ? { type: "underline" as const, index: underlineTagMatch.index, length: underlineTagMatch[0].length, match: underlineTagMatch } : null,
      underlinePlusMatch && underlinePlusMatch.index !== undefined ? { type: "underline" as const, index: underlinePlusMatch.index, length: underlinePlusMatch[0].length, match: underlinePlusMatch } : null,
      strikeMatch && strikeMatch.index !== undefined ? { type: "strike" as const, index: strikeMatch.index, length: strikeMatch[0].length, match: strikeMatch } : null,
      highlightMatch && highlightMatch.index !== undefined ? { type: "highlight" as const, index: highlightMatch.index, length: highlightMatch[0].length, match: highlightMatch } : null,
      codeMatch && codeMatch.index !== undefined ? { type: "code" as const, index: codeMatch.index, length: codeMatch[0].length, match: codeMatch } : null,
      linkMatch && linkMatch.index !== undefined ? { type: "link" as const, index: linkMatch.index, length: linkMatch[0].length, match: linkMatch } : null,
      urlMatch && urlMatch.index !== undefined ? { type: "url" as const, index: urlMatch.index, length: urlMatch[0].length, match: urlMatch } : null,
    ].filter((c): c is { type: "bold" | "underline" | "strike" | "highlight" | "code" | "link" | "url"; index: number; length: number; match: RegExpMatchArray } => c !== null);

    candidates.sort((a, b) => a.index - b.index);
    const earliest = candidates[0];

    if (!earliest) {
      if (remaining.includes("<span")) {
        parts.push(
          <span key={`raw-html-${keyIdx++}`} dangerouslySetInnerHTML={{ __html: remaining }} />
        );
      } else {
        parts.push(remaining);
      }
      break;
    }


    // Push text before match
    if (earliest.index > 0) {
      parts.push(remaining.substring(0, earliest.index));
    }

    // Push formatted match
    if (earliest.type === "bold") {
      parts.push(
        <strong key={`b-${keyIdx++}`} className="text-white font-bold">
          {renderInline(earliest.match[1])}
        </strong>
      );
    } else if (earliest.type === "underline") {
      parts.push(
        <u key={`u-${keyIdx++}`} className="underline underline-offset-2 decoration-1 text-white">
          {renderInline(earliest.match[1])}
        </u>
      );
    } else if (earliest.type === "strike") {
      parts.push(
        <s key={`s-${keyIdx++}`} className="line-through opacity-70">
          {renderInline(earliest.match[1])}
        </s>
      );
    } else if (earliest.type === "highlight") {
      parts.push(
        <mark key={`m-${keyIdx++}`} className="bg-amber-500/20 text-amber-200 px-1 py-0.5 rounded">
          {renderInline(earliest.match[1])}
        </mark>
      );
    } else if (earliest.type === "code") {
      parts.push(
        <code
          key={`c-${keyIdx++}`}
          className="px-1.5 py-0.5 rounded bg-gp-ink-750 text-gp-coral-25 font-mono text-2xs border border-gp-ink-650"
        >
          {earliest.match[1]}
        </code>
      );
    } else if (earliest.type === "link") {
      const label = earliest.match[1];
      const url = earliest.match[2];
      parts.push(
        <a
          key={`l-${keyIdx++}`}
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-0.5 text-gp-sky hover:text-gp-sky-50 underline underline-offset-2 transition-colors"
        >
          <span>{label}</span>
          <ExternalLink className="w-2.5 h-2.5 ml-0.5 inline opacity-70" />
        </a>
      );
    } else if (earliest.type === "url") {
      const url = earliest.match[1];
      parts.push(
        <a
          key={`url-${keyIdx++}`}
          href={url}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-0.5 text-gp-sky hover:text-gp-sky-50 underline truncate max-w-xs align-bottom"
        >
          <span>{url}</span>
          <ExternalLink className="w-2.5 h-2.5 ml-0.5 inline opacity-70" />
        </a>
      );
    }

    remaining = remaining.substring(earliest.index + earliest.length);
  }

  return <>{parts}</>;
}

// Basic sanitizer to allow safe styling, callouts, tables, underlines
function sanitizeNotionHtml(html: string): string {
  // Strip harmful script / iframe tags
  return html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, "")
    .replace(/<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi, "");
}
